                portSumsOfShuffledQuadAbsoluteDifferencesU8ToU16ConstantB(a),
                highwaySumsOfShuffledQuadAbsoluteDifferencesU8ToU16ConstantB(a),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

